/**
 * Pulls a Meson-lookupable identifier out of free-form text.
 *
 * Users type whatever they like into a ticket form: a swap ID, the source or destination transaction hash, a full explorer URL, a third-party explorer URL, or all of it wrapped in a sentence.
 * The explorer's own search endpoint resolves any of those to a swap ID, so our job is only to find the candidate token(s) in the text and hand them over in a sensible order.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L28   Shared
// L32     matches()
// L37     stripFormatting()
// L40     dedupe()
// L53   Swap identifiers
// L60     MESON_SWAP_LINK
// L65     HEX32
// L71     CHAIN_TX_LINK
// L74     BARE_HEX32
// L80     SOLANA_SIGNATURE
// L95     extractCandidates()
// L107  Wallet addresses
// L112    URL_ADDRESS_PATH
// L115    EVM_ADDRESS
// L118    TRON_ADDRESS
// L121    BTC_BECH32
// L124    BASE58_ADDRESS
// L134    extractAddressCandidates()
// ----- end of contents -----

// =============================================================================
//   Shared
// =============================================================================

const matches = (text, re) => [...text.matchAll(re)].map((m) => m[1] ?? m[0])

/**
 * Strip Discord formatting that commonly glues itself to a pasted hash: backticks, angle-bracketed links, bold/italic/strike/spoiler markers.
 */
const stripFormatting = (text) => text.replace(/[`*_~|<>]/g, ' ')

/** Flatten priority tiers into one list, first occurrence wins (case-insensitive). */
function dedupe (tiers) {
  const seen = new Set()
  const out = []
  for (const raw of tiers.flat()) {
    const id = raw.trim()
    const key = id.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    out.push(id)
  }
  return out
}

// =============================================================================
//   Swap identifiers
// =============================================================================

// Patterns below are in the order they are tried (see extractCandidates).

/** 1. Meson explorer link — the swap ID is taken from the URL. */
const MESON_SWAP_LINK = /meson\.fi\/swap\/([0-9a-zA-Z]{32,90})/g

/**
 * 2. 0x + 64 hex: a Meson swap ID or an encoded swap. A bare EVM transaction hash has the same shape and lands here too — harmless, Meson resolves both.
 */
const HEX32 = /0x[0-9a-fA-F]{64}/g

/**
 * 3. Source explorer link — the hash is taken from a /tx/<hash> path segment (or /transaction/, /txn/, /txblock/ on Tron, CKB, TON, Aptos, Sui).
 *    Matching the path rather than the host covers etherscan, solscan, tronscan, mempool.space, … without a per-host table.
 */
const CHAIN_TX_LINK = /\/(?:tx|transaction|txn|txblock)\/([0-9a-zA-Z]{32,90})/g

/** 4a. Bare 64-hex with no 0x — how Tron and Bitcoin hashes are usually pasted. */
const BARE_HEX32 = /\b[0-9a-fA-F]{64}\b/g

/**
 * 4b. Base58 Solana transaction signatures (86–88 chars).
 *     The lower bound must stay well above 44: Solana *wallet addresses* are base58 too (32–44 chars), and matching them here would look a user's wallet up as if it were a swap.
 */
const SOLANA_SIGNATURE = /\b[1-9A-HJ-NP-Za-km-z]{80,90}\b/g

/**
 * Swap-shaped identifiers in free-form text, in the order to try them.
 *
 * Meson's search resolves a swap ID, an encoded swap and a tx hash the same way, and a link is looked up by the value inside it — so this order only decides which is tried first, never what is found.
 * It runs from the most Meson-specific to the least, and within each a link (which says what it is) before a bare value (which could be noise):
 *   1. Meson explorer link      → swap ID
 *   2. swap ID / encoded swap   (0x + 64 hex)
 *   3. source explorer link     → tx hash
 *   4. bare source hash         (Tron/BTC hex, Solana signature)
 * A wallet address comes after all of these, as a separate lookup (tickets.js).
 * @param {string} text
 * @returns {string[]} de-duplicated candidates, first to try first
 */
export function extractCandidates (text) {
  if (!text || typeof text !== 'string') return []
  const clean = stripFormatting(text)
  return dedupe([
    matches(clean, MESON_SWAP_LINK),
    matches(clean, HEX32),
    matches(clean, CHAIN_TX_LINK),
    matches(clean, BARE_HEX32),
    matches(clean, SOLANA_SIGNATURE),
  ])
}

// =============================================================================
//   Wallet addresses
// =============================================================================

/** An /address/<id> path segment from any explorer URL. */
const URL_ADDRESS_PATH = /\/address\/([0-9a-zA-Z]{20,90})/g

/** EVM address: 0x + 40 hex (distinct from the 64-hex swap/tx pattern above). */
const EVM_ADDRESS = /\b0x[0-9a-fA-F]{40}\b/g

/** Tron address: 'T' + 33 base58 characters. */
const TRON_ADDRESS = /\bT[1-9A-HJ-NP-Za-km-z]{33}\b/g

/** Bitcoin bech32 (bc1...). Legacy/P2SH addresses are covered by BASE58_ADDRESS below. */
const BTC_BECH32 = /\bbc1[a-z0-9]{25,87}\b/g

/** Base58 blob in the address-length range — Solana, legacy Bitcoin, and similar chains. */
const BASE58_ADDRESS = /\b[1-9A-HJ-NP-Za-km-z]{25,44}\b/g

/**
 * Pull a wallet-address candidate out of free-form text (an explorer link, a bare address, or an address mentioned in a sentence).
 *
 * @param {string} text
 * @param {{allowFallback?: boolean}} [opts] `allowFallback` (default true) falls back to the whole trimmed input when no known address shape matches — fine when a human typed this as the CLI's argument, but wrong for scanning arbitrary ticket text (a stray sentence would "match" and get looked up as if it were an address).
 *   Auto-detection should pass `false`.
 * @returns {string[]} de-duplicated candidates, most-likely first
 */
export function extractAddressCandidates (text, { allowFallback = true } = {}) {
  if (!text || typeof text !== 'string') return []
  const clean = stripFormatting(text)

  const out = dedupe([
    matches(clean, URL_ADDRESS_PATH),
    matches(clean, EVM_ADDRESS),
    matches(clean, TRON_ADDRESS),
    matches(clean, BTC_BECH32),
    matches(clean, BASE58_ADDRESS),
  ])
  // Nothing matched a known shape (e.g. an Aptos/Sui/Starknet/CKB/TON address) — fall back to the trimmed input verbatim rather than refusing it outright.
  if (!out.length && allowFallback) {
    const trimmed = clean.trim()
    if (trimmed) out.push(trimmed)
  }
  return out
}
